    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate M as a power of two, and r,s as odd coprime integers.
# We ensure the problem is nontrivial by choosing moderately large exponents.
# The largest possible alpha under the strengthened proportional condition will be (r+s)*M - 1.
# We expose this as n_upper_bound in the wrapper while alpha is the unknown to be determined.
# To avoid trivial instances, we choose B in [8, 14] so M ranges 256..16384.

# Helper to draw an odd integer within range
def draw_odd(lo, hi):
    # inclusive range, ensure odd
    while True:
        x = rng.randint(lo, hi)
        if x % 2 == 1:
            return x

# Helper to ensure coprime odd pair
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Retry loop for robust generation
for _ in range(100):
    B = rng.randint(9, 13)  # moderate size to ensure difficulty
    M = 1 << B
    # choose odd r,s coprime and not too large to avoid trivial or degenerate cases
    r = draw_odd(3, 19)
    s = draw_odd(3, 19)
    # ensure coprime and not equal (to make the proportion nontrivial)
    if gcd(r, s) != 1 or r == s:
        continue
    # compute theoretical upper bound
    n_upper = (r + s) * M - 1
    # alpha is the unknown to be solved in the problem; we do not leak the answer in wrapper.
    return {
        'alpha': None,  # placeholder; solver must determine the largest possible alpha
        'm_bound': M,
        'r_coeff': r,
        's_coeff': s,
        'n_upper_bound': n_upper
    }
# Fallback in the unlikely event of repeated failure
B = 10
M = 1 << B
r, s = 3, 5
n_upper = (r + s) * M - 1
return {'alpha': None, 'm_bound': M, 'r_coeff': r, 's_coeff': s, 'n_upper_bound': n_upper}

    def verifier(assign):
# Validate domain constraints and compute the correct largest alpha.
# The problem: For any sequence of alpha positive integers <= M, and for all contiguous intervals,
# forbid r * sum(A) = s * sum(complement) for any non-empty proper subset A.
# Known tight bound under conditions M=2^B and r,s odd coprime: max alpha = (r+s)*M - 1.

