    return (False, None)
if M <= 0 or r <= 0 or s <= 0:
    return (False, None)
# M must be a power of two
if M & (M - 1) != 0:
    return (False, None)
# r and s must be odd coprime and distinct
def gcd(a,b):
    while b:
        a,b = b, a % b
    return a
if r % 2 == 0 or s % 2 == 0:
    return (False, None)
if gcd(r, s) != 1 or r == s:
    return (False, None)
# Compute the answer
answer_val = (r + s) * M - 1
# Cross-check declared upper bound for consistency
if n_upper != answer_val:
    # mismatch in provided upper bound
    return (False, None)
# Return the AIME-style formatted answer
ans_str = f"### The final answer is: \\\boxed{{{answer_val}}}"
return (True, ans_str)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

